import { View, Text, FlatList, Pressable, StyleSheet } from "react-native";
import { useState } from "react";
import { registerRootComponent } from "expo";

const PRODUCTS = [
  { id: "1", name: "Чихэвч", price: "159,000₮" },
  { id: "2", name: "Гар цаг", price: "249,000₮" },
  { id: "3", name: "Нарны шил", price: "89,000₮" },
];

function App() {
  const [selected, setSelected] = useState(null);

  if (selected) {
    return (
      <View style={styles.detail}>
        <Text nativeID="dname" style={styles.dname}>{selected.name}</Text>
        <Text nativeID="dprice" style={styles.dprice}>{selected.price}</Text>
        <Pressable nativeID="back" style={styles.btn} onPress={() => setSelected(null)}>
          <Text style={styles.btnText}>← Жагсаалт руу буцах</Text>
        </Pressable>
      </View>
    );
  }

  return (
    <FlatList
      style={styles.screen}
      data={PRODUCTS}
      keyExtractor={(item) => item.id}
      renderItem={({ item }) => (
        <Pressable testID="row" style={styles.row} onPress={() => setSelected(item)}>
          <Text style={styles.name}>{item.name}</Text>
        </Pressable>
      )}
    />
  );
}

const styles = StyleSheet.create({
  screen: { flex: 1, backgroundColor: "#f5f6f8" },
  row: { backgroundColor: "#fff", padding: 16, margin: 8, borderRadius: 12 },
  name: { fontSize: 16, fontWeight: "600" },
  detail: { flex: 1, padding: 24, gap: 12, justifyContent: "center" },
  dname: { fontSize: 26, fontWeight: "bold" },
  dprice: { fontSize: 20, color: "#2563eb", fontWeight: "bold" },
  btn: { marginTop: 12 },
  btnText: { color: "#2563eb", fontSize: 16 },
});

registerRootComponent(App);
